app.get('/api/workbooks/:id/history', (req, res) => {
  const { sheetId, address } = req.query;
  if (typeof sheetId !== 'string' || typeof address !== 'string' || !addressRe.test(address)) return fail(res, 400, 'Valid sheetId and address are required');
